CREATE TABLE IF NOT EXISTS communication_governance_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,thread_id TEXT NOT NULL,universal_conversation_id TEXT NOT NULL,participant_reference TEXT,guest_reference TEXT,reservation_reference TEXT,consent_status TEXT NOT NULL,consent_source TEXT,quiet_hours_timezone TEXT NOT NULL,quiet_hours_start INTEGER NOT NULL,quiet_hours_end INTEGER NOT NULL,retention_policy_key TEXT NOT NULL,sla_due_at TEXT,assigned_user TEXT,tags_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,universal_conversation_id));
CREATE TABLE IF NOT EXISTS communication_delivery_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,thread_id TEXT NOT NULL,draft_id TEXT,external_delivery_id TEXT NOT NULL,provider_event_id TEXT NOT NULL,delivery_status TEXT NOT NULL,signature_verified INTEGER NOT NULL,idempotency_key TEXT NOT NULL,evidence_json TEXT NOT NULL,occurred_at TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(organization_id,property_id,provider_event_id),UNIQUE(organization_id,property_id,idempotency_key));
CREATE TABLE IF NOT EXISTS communication_certification_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,status TEXT NOT NULL,provider_mode TEXT NOT NULL,total_cases INTEGER NOT NULL,passed_cases INTEGER NOT NULL,production_enabled INTEGER NOT NULL DEFAULT 0,real_message_sent INTEGER NOT NULL DEFAULT 0,evidence_json TEXT NOT NULL,executed_by TEXT NOT NULL,executed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS communication_governance_queue_idx ON communication_governance_profiles(organization_id,property_id,consent_status,sla_due_at);
CREATE INDEX IF NOT EXISTS communication_delivery_lifecycle_idx ON communication_delivery_events(organization_id,property_id,thread_id,occurred_at);
CREATE INDEX IF NOT EXISTS communication_certification_history_idx ON communication_certification_runs(organization_id,property_id,executed_at);
